def find_file(tar_file: IoReader, filename: Str) -> (TarHeader, IoReader, error):
  reader = tar.new_reader(tar_file)
  loop:
    (header, err) = reader.next()
    if err == io.eof:
      break
    if err != None:
      return (None, None, errors.trace(err))
    if header.name == filename:
      return (header, reader, None)
  return (None, None, errors.not_foundf(filename))
