	saturday := time.Date(2026, 1, 3, 12, 0, 0, 0, time.UTC) // Sat
	monday := time.Date(2026, 1, 5, 12, 0, 0, 0, time.UTC)   // Mon
	if !IsWeekend(saturday) {
		t.Error("saturday should be weekend")
	}
	if IsWeekend(monday) {
		t.Error("monday should not be weekend")
	}
}

